var theShader;
var img0;

function preload() {
	theShader = createShader(vert, frag);
	img0 = loadImage("https://openprocessing.org/sketch/2366020/files/IMG_2616.heic");
}

function setup() {
	createCanvas(windowWidth, windowWidth*.75, WEBGL);
	background(100);
	window.simulatedMouseX = width/2;
}

function draw() {
	noStroke();
	shader(theShader);
	theShader.setUniform("tex0", img0);
	theShader.setUniform("canvasSize", [width, height]);
	theShader.setUniform("mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height]);
	theShader.setUniform("time", frameCount);
	quad(-1, 1, 1, 1, 1, -1, -1, -1)
}

// === Tab: vert ===
const vert = `#version 300 es
  precision mediump float;

	in vec4 aPosition;
  in vec2 aTexCoord;

  out vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    gl_Position = aPosition;
  }
`;

// === Tab: frag ===
const frag = `#version 300 es
  precision mediump float;

  uniform sampler2D tex0;
  uniform vec2 canvasSize;
  uniform vec2 mouse;
  uniform float time;

	const float TAU = 6.283185;

	float dist2(vec2 v1, vec2 v2) {
		vec2 diff = v1 - v2;
		float ratio = canvasSize.y / canvasSize.x;
		diff *= vec2(1, ratio);
		return length(diff);
	}

	vec2 rotate(vec2 v, float a) {
		float ratio = canvasSize.y / canvasSize.x;
		v *= vec2(1, ratio);
		float s = sin(a);
		float c = cos(a);
		mat2 m = mat2(c, s, -s, c);
		return m * v / vec2(1, ratio);
	}

	vec3 chromaticAbberationX(sampler2D tex, vec2 uv, float x, float d, float strength) {
		vec2 newUVR = uv;
		vec2 newUVG = uv;
		vec2 newUVB = uv;
		if(abs(uv.x - x) < d) {
			newUVR.x += strength * 20. * (d - abs(uv.x - x));
			newUVB.x -= strength * 20. * (d - abs(uv.x - x));
		}
		float R = texture(tex, newUVR).r;
		float G = texture(tex, newUVG).g;
		float B = texture(tex, newUVB).b;
		vec3 col = vec3(R, G, B);
		return col;
	}

  in vec2 vTexCoord;
  out vec4 fragColor;
  void main() {
    vec2 uv = vTexCoord;
		float ratio = canvasSize.y / canvasSize.x;
		vec3 col = vec3(0);
		col = chromaticAbberationX(tex0, uv, mouse.x, 0.2, 0.01);
		if(false) { //TURN OFF
		if(dist2(uv, mouse) < 0.1) {
			// col = texture(tex0, uv + vec2(sin(time / 10.) * 0.5 * (0.1 - dist2(uv, mouse)), cos(time / 10.) * 0.5 / ratio * (0.1 - dist2(uv, mouse)))).rgb;
			// col = texture(tex0, uv + (uv - mouse) * 50. * (0.1 - dist2(uv, mouse))).rgb;
			col = texture(tex0, mouse + (rotate(uv - mouse, TAU * 0.25 * 10. * (0.1 - dist2(uv, mouse))))).rgb;
		} else {
			col = texture(tex0, uv).rgb;
		}
		}
    fragColor = vec4(col, 1.);
  }
`;

